// MakeConfigurationError builds a loom.ServiceError from an error.
func MakeConfigurationError(err error) *loom.ServiceError {
	serr := loom.NewServiceError(err, "configuration_error", false, false, false)
	loom.WithErrorRemedy(serr, &loom.ErrorRemedy{
		Code:        "argo.configure",
		SafeMessage: "Argo API is not configured.",
		RetryHint:   "Set ARGO_BASE_URL and authentication environment variables, then retry.",
	})
	return serr
}

// MakeArgoAPIError builds a loom.ServiceError from an error.
func MakeArgoAPIError(err error) *loom.ServiceError {
	serr := loom.NewServiceError(err, "argo_api_error", false, true, false)
	loom.WithErrorRemedy(serr, &loom.ErrorRemedy{
		Code:        "argo.api.retry",
		SafeMessage: "The Argo API request failed.",
		RetryHint:   "Verify Argo connectivity and credentials, then retry.",
	})
	return serr
}

